def solve(g):
    from collections import Counter
    c=Counter(v for r in g for v in r)
    # find rectangle borders: colors where cells form a hollow rect perimeter
    out=[r[:] for r in g]
    rects=[]; noise={}
    for col in set(v for r in g for v in r)-{0}:
        cells=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==col]
        rs=[i for i,j in cells]; cs=[j for i,j in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        if len(cells)==2*(r1-r0+1)+2*(c1-c0+1)-4 and r1>r0+1 and c1>c0+1:
            rects.append((r0,r1,c0,c1,col))
        else:
            noise[col]=len(cells)
    rects.sort(key=lambda R:abs(R[2]-R[3])+abs(R[0]-R[1]))
    used=set()
    for r0,r1,c0,c1,col in rects:
        area=(r1-r0-1)*(c1-c0-1); need=area//2
        # find unused noise color with count == need
        cand=[nc for nc,n in noise.items() if nc not in used and n==need]
        nc=cand[0]; used.add(nc)
        for i in range(r0+1,r1):
            for j in range(c0+1,c1):
                out[i][j]= nc if (i+j)%2==(r0+1+c0+1)%2 else 0
    # remove noise cells
    border={(i,j) for r0,r1,c0,c1,col in rects for i,j in
            [(r0,jj) for jj in range(c0,c1+1)]+[(r1,jj) for jj in range(c0,c1+1)]+
            [(ii,c0) for ii in range(r0,r1+1)]+[(ii,c1) for ii in range(r0,r1+1)]}
    for i,r in enumerate(out):
        for j in range(len(r)):
            if out[i][j]!=0 and (i,j) not in border: out[i][j]=0
    return out
